\caption{PSGLD for IRL}
\begin{algorithmic}[1]
\State parameters: step size $\epsilon$, inverse temperature $\beta$, kernel scale $\Delta$, re-sampling distribution scale $\gamma$
\State initialize $\alpha_0 \sim \pi_{0,\gamma}$
\While{$k \geq 0$}
        \State obtain $\theta_k$ from Algorithm~alg:sgd
        \If{$k\geq 1$}
        \State $\hat{\nabla}J(\theta_k) = \frac{1}{\eta}(\theta_k-\theta_{k-1}),\quad K_{k-1} = \frac{1}{\Delta^N} K(\frac{\theta_{k-1} - \alpha_{k-1}}{\Delta})$
        \State sample $w_k \sim \mathcal{N}(0,I_{N})$
        \State  $\alpha_k \gets \alpha_{k-1} - \epsilon\biggl[K_{k-1} \frac{\beta}{2} \hat{\nabla} J (\theta_k) \,\color{black}{-}\, \nabla \pi_{0,\gamma}(\alpha_{k-1})\biggr]\pi_{0,\gamma}(\alpha_{k-1})+ \sqrt{\epsilon}\pi_{0,\gamma}(\alpha_{k-1}) w_k$
        \EndIf
\EndWhile


\end{algorithmic}

{\color{black}
\caption{\color{black}{Cost Reconstruction by Sequential-Sampling Kernel Density Estimation}}
\begin{algorithmic}[1]
\State Initialize 2-Wasserstein proximity $\rho > 0$, number of sampling streams $T$, sampling region $\Theta \subset \mathbb{R}^{N}$
\State \textcolor{black}{Set kernel function $\mathcal{K}$ and $T$-dependent bandwidth $b_T$.}
\State Take $\delta \in \textcolor{black}{\left[0, \exp\left(-\frac{1}{\beta c_{LS}}\right) \right]}$ s.t. $\delta\left[C_4 + \sqrt{2c_{LS} C_3} \right] + \delta\sqrt{10c_{LS}N\log\left(1/\delta\right)} \leq \rho$, \,\,$\epsilon \leq \left(\frac{\delta}{\log(1/\delta)} \right)^2$, $\hat{k}$ as (21) 
\State Initialize parameters $\Delta, \gamma$ as (22), (23), respectively.



\State Set $k=0, \,S=\emptyset, \,q=0$.
\For{$i=1: \textcolor{black}{T}$}
\State \textcolor{black}{Initialize $i$'th PSGLD (Algorithm~alg:psgld) stream by $\alpha_0^i \overset{\textcolor{black}{i.i.d.}}{\sim} \pi_{0,\gamma}$}.



\While{$k \leq \textcolor{black}{q +} \hat{k}$}   
    \State $k = k+1$ \textcolor{black}{\algorithmiccomment{Iterate $i$'th Algorithm 2 stream, taking $\hat{\nabla}J(\theta_k)$ from Algorithm~alg:sgd as input.}}
    \If{$k = \textcolor{black}{q +} \hat{k}$}
        \State \textcolor{black}{Take sample $\alpha_k^i$} \textcolor{black}{\algorithmiccomment{Sample from $\pi_{\hat{k}}$. By initializations (Lines 1-3) we have $\mathcal{W}_2(\pi_{\hat{k}},\pi_{\infty}) \leq \rho$.}}
        \If{$\alpha_k^i \in \Theta$}

            \State \textcolor{black}{$S \leftarrow S \cup \alpha_k^i$}
        \EndIf
    \EndIf
\EndWhile
\textcolor{black}{\While{$\|\hat{\nabla}J(\theta_k)\| > c_{opt}$} \algorithmiccomment{Wait until SGD (Algorithm~alg:sgd) re-initializes.}
\EndWhile}
\State \textcolor{black}{$q = k$} \textcolor{black}{\algorithmiccomment{$q$ is a dummy variable holding the re-initialization iterate value}}
\EndFor

\textcolor{black}{\If{$|S| \geq 1$}
    \State \textcolor{black}{Set $b_S = b_T\sqrt{\frac{T}{|S|}}$, and construct density estimate $\hat{\pi}(\cdot) = \frac{1}{b_S |S|}\sum_{\alpha_k^i \in S}\mathcal{K}\left(\frac{\cdot - \alpha_k^i}{b_S^{1/N}} \right)$.}


\State \textcolor{black}{Construct cost function $\hat{J}(\cdot) = -\frac{1}{\beta}\log(\hat{\pi}(\cdot))$, for $\beta$ in Algorithm~alg:psgld.}
\EndIf}
\end{algorithmic}
}

If $\pi$ satisfies a logarithmic-Sobolev inequality with constant $c$, then, for any $\mu \ll \pi$

\begin{equation*}
    \mathcal{W}_2(\mu,\pi) \leq \sqrt{2cD(\mu||\pi)}
\end{equation*}

Let $\mu_t := \textrm{Law}(X(t))$. If $\pi$ satisfies a logarithmic-Sobolev inequality with constant $c$, then 
\begin{equation*}
    D(\mu_t || \pi) \leq D(\mu_0 || \pi)e^{-2t/c}
\end{equation*}

For $\beta$ satisfying Assumption~ass:beta, the Gibbs measure $\pi_{\infty}$ satisfies a logarithmic Sobolev inequality with constant $c_{LS}$:
\begin{align}
    \begin{split}

        &0 \leq c_{LS} \leq \frac{2\beta L_{\nabla J}}{\gamma} + \frac{2}{\beta L_{\nabla J}}  + \frac{1}{\lambda} \biggl(\frac{2\beta L_{\nabla J}}{\gamma}\left( \kappa + \gamma\left(\kappa_0 + \frac{(\beta b + N)\bar{\pi}_{0,\gamma} + 2I}{(m\beta)\bar{\pi}_{0,\gamma}}\right)\right) + 2\biggr)
    \end{split}
\end{align}

Consider the PSGLD Algorithm~alg:psgld with iterates $\alpha_k \in \mathbb{R}^{N}$. Recall $c_{LS}$ is the logarithmic-Sobolev constant for diffusion process~(eq:ct_diff) ($c_{LS}$ will be bounded in (eq:lsconst)). For any 
     \begin{equation}

     \delta \in \left[0,\exp\left(-\frac{1}{\beta c_{LS}}\right)\right]
    \end{equation}
    choose step size $\epsilon$ according to (20), number of iterations $k$ according to (21), kernel scale $\Delta$ according to (22), and sampling distribution $\pi_{0,\gamma}$ with $\gamma$ satisfying (23). Then, under assumptions (ass:Msmooth)-(ass:beta), the 2-Wasserstein distance between the distribution $\pi_{k}$, generated by the PSGLD algorithm, and the Gibbs measure $\pi_{\infty}$ (2), satisfies: 
    \begin{align}
    \begin{split}

       &\mathcal{W}_2(\pi_{k},\pi_{\infty}) \leq \delta\left[C_4 + \sqrt{2c_{LS} C_3} \right] + \delta\sqrt{10c_{LS}N\log\left(1/\delta\right)}
    \end{split}
    \end{align}
    $C_3, C_4$ are constants dependent on structural specifications of $J$ and the process (eq:dt_sgld), provided explicitly in Appendix~.1. $c_{LS}$ is the logarithmic-Sobolev constant bounded explicitly in Proposition~4.
